We start by proving the following 2 auxiliary statements:

\begin{lemma}
\label{lem:memory}
With probability at least $1 - 1/(nT)^{\omega(1)}$, the pool size of $\mP$ never exceeds $O(\log^{11}(nT))$. 
Furthermore, the memory usage of Algorithm \ref{algo:full} is bounded by $O(\log^{22}(nT))$ words.
\end{lemma}
\begin{proof}
By Lemma \ref{lem:pool_size_full}, we know that the size of pool $\mP$ satisfies $|\mP| = |\mP_{1, \cdot} \cup \cdots \cup \mP_{R, \cdot}| \leq O(\log^{11}(nT))$. 
The {\sc Merge} procedure needs to know the loss on each interval $\Gamma_{i, j}$ of $i, j\in \mP$, this takes $O(\log^{22}(nT))$ words of memory. 
By Theorem \ref{thm:sleeping}, the {\sc MonocarpicExpert} requires memory $O(|\mP|\log^2(nT)) = O(\log^{13}(nT))$ . In summary, the total memory is bounded by $O(\log^{22}(nT))$.
We conclude the proof here.
\end{proof}

\begin{lemma}
\label{lem:bad-size-full}
With probability at least $1 - 1/(nT)^{\omega(1)}$, $|\mH_r| \leq O(n\log^{11}(nT))$ holds for any $r\in [R]$.
\end{lemma}
\begin{proof}
Recall we first fixed the loss sequence $\ell_1, \ldots, \ell_{T}$ as well as the set of sampled and active experts $\{Y_a\}_{a\in K}$.
For any $r\in [R]$, we prove the size of pool $\mP$ at the end satisfies 
\[
\Pr\left[|\mP|\geq \frac{|\mH_r|}{4n} \mid \{Y_a\}_{a\in K}, \{\ell_t\}_{t\in[T]} \right] \geq \frac{1}{2},
\]
whenever $|\mH_r| \geq \Omega(n)$. Here the probability is taken over the randomness of the remaining  {\em sampled and passive} experts. 

The proof is similar to Lemma \ref{lem:base-size}.
Let $W_a$ be the set of sampled and passive experts of timestep $a$. For any timestep $a \in \mH_r$, by our assignment mechanism (Algorithm \ref{algo:sequence}), the expert $i^{*} \notin Y_{a}$ (otherwise $i^{*}$ is covered by itself.)
The probability that $i^{*} \in W_a$ obeys
\begin{align*}
\Pr\left[i^{*}\in W_a | \{Y_a\}_{a\in K}, \{\ell_t\}_{t\in[T]} \right] = &~  \Pr[i^{*}\in W_a | i^{*}\notin Y_{a}] \\
\geq &~ \Pr[i^{*}\in W_a] = \frac{1}{n} \cdot \left(1 - \frac{1}{\log^4 (n)}\right)^{R\times 2L \times 2K} \geq \frac{1}{2n}.
\end{align*}

The key observation is that once $i^{*} \in W_{a}$, i.e., $i^{*}$ is sampled while passive at timestep $t$, it would survive till the end. This is because the filter set $\mF$, the estimate size $s$ and the set of alive active experts are all fully determined by the sampled and active experts $\{Y_a\}_{a\in K}$ and the loss sequence $\{\ell_t\}_{t\in [T]}$, which has already been fixed when defining the eviction time $t(a)$. 
Therefore, if a passive expert $i^{*}$ enters at timestep $a$, it survives till the end.

The event of $i^{*}\in W_a$ are independent for $a \in \mH_r$ (condition on the loss sequence and $\{Y_a\}_{a\in [K]}$), hence, by Chernoff bound, one has
\begin{align*}
\Pr\left[|\mP|\leq \frac{|\mH_r|}{4n} \mid \{Y_a\}_{a\in K}, \{\ell_t\}_{t\in[T]}\right] \leq &~ \Pr\left[\sum_{a\in \mH_r}\mathsf{1}\{i^{*}\in W_{a}\} \leq \frac{|\mH_r|}{4n} \mid \{Y_a\}_{a\in K}, \{\ell_t\}_{t\in[T]}\right]\\
\leq &~ \exp(-|\mH_r|/16n). 
\end{align*}

Note we have already proved in Lemma \ref{lem:memory} that $|\mP| \geq  \Omega(\log^{11}(nT))$ happens with probability at most $1/(nT)^{\omega(1)}$, this implies 
\[
\Pr[|\mH_r|\geq \Omega(n\log^{11}(nT))] \leq 1/(nT)^{\omega(1)}.
\] 
We conclude the proof here.
\end{proof}

With the above in mind, we are now ready to prove the main statement:

\begin{proof}
In the proof, we first fix the loss sequence $\{\ell_t\}_{t\in [T]}$ and the set of sampled and active experts $\{Y_a\}_{a\in K}$. 
Now we can use the epoch assignment mechanism (Algorithm \ref{algo:sequence}) and split the entire sequence $[T]$ into a collection of intervals $\{I_{\tau}\}_{\tau \in [\tau_{\max}]}$.

We first categorize the intervals based on their length. With probability at least $1-1/(nT)^{\omega(1)}$, we have
\begin{align}
\sum_{t \in [T]}\ell_{t}(i_t) -\sum_{t \in [T]}\ell_{t}(i^{*}) = &~ \sum_{r=1}^{R-1}\sum_{\mI \in L_{r}\setminus L_{r+1}}\sum_{t\in \mI}(\ell_{t}(i_t) -  \ell_{t}(i^{*})) + \sum_{\mI \in L_R}\sum_{t\in \mI}(\ell_{t}(i_t) -  \ell_{t}(i^{*}))\notag \\
\leq &~ \sum_{r=1}^{R-1}\sum_{\mI \in L_{r}\setminus L_{r+1}}\sum_{t\in \mI}(\ell_{t}(i_t) -  \ell_{t}(i^{*})) + O(|\mH_{R-1}|)\notag \\
\leq &~ \sum_{r=1}^{R-1}\sum_{\mI \in L_{r}\setminus L_{r+1}}O\left(\sqrt{|\mI|}\log^6 (nT)\right) + O(|\mH_{R-1}|).\label{eq:regret-last1}
\end{align}
The first step holds from $[T] = \cup_{\mI\in L_1} \mI$, the second step uses the naive bound of
\[
\sum_{\mI \in L_R}\sum_{t\in \mI}(\ell_{t}(i_t) -  \ell_{t}(i^{*})) \leq \sum_{\mI\in L_{R}}|\mI| \leq |\mH_{R-1}|\cdot B_{R-1} = O(|\mH_{R-1}|),
\]
and the last step follows from the interval regret bound of Lemma \ref{lem:interval-regret-apply}. 

We bound the regret of each group separately.
Note for any $r\in [R-1]$, one has 
\begin{align}
\sum_{\mI \in L_{r}\setminus L_{r+1}}\sqrt{|\mI|} \leq &~ \sqrt{| L_{r}\setminus L_{r+1}| \cdot \sum_{\mI \in L_{r} \backslash L_{r+1}}|\mI|}\notag \\
\leq &~ |\mH_{r-1}| B_{r-1} \cdot  \sqrt{\frac{1}{B_{r}}} \notag \\
\leq &~ \left\{
\begin{matrix}
|\mH_{r-1}| \cdot \sqrt{2T/n}  & r\geq 2\\
\sqrt{nT}& r = 1
\end{matrix}
\right..\label{eq:regret-last2}
\end{align}
The first step follows from Cauchy-Schwarz, the second step follows from (1) the length of an interval $\mI \in L_{r} \backslash L_{r+1}$ satisfies $|\mI| \in [B_{r}: B_{r-1})$ and (2) $\sum_{\mI \in L_{r} \backslash L_{r+1}}|\mI| \leq |\mH_{r-1}| \cdot B_{r-1}$ (see Lemma \ref{lem:obv-interval}). 
The last step follows from the choice of $\{B_r\}_{r\in [R]}$. Note we slightly abuse notation and set $|\mH_{0}| = 1$ and $B_{0} = T$.

We can bound the RHS of Eq.~\eqref{eq:regret-last1} using Eq.~\eqref{eq:regret-last2}. With probability at least $1-1/(nT)^{\omega(1)}$, one has
\begin{align}
 &~ \sum_{r=1}^{R-1}\sum_{\mI \in L_{r}\setminus L_{r+1}}O\left(\sqrt{|\mI|}\log^6 (nT)\right) + O(|\mH_{R-1}|)\notag\\
\leq &~ O\left( \sqrt{n T}\log^6(nT) + \sum_{r=2}^{R-1} |\mH_{r-1}|\cdot \sqrt{T/n}\log^6(nT)  + |\mH_{R-1}|\right)\notag\\
\leq &~ \wt{O}\left(\sqrt{T/n}\right),
\label{eq:regret-last3}
\end{align}
where the second step follows from Lemma \ref{lem:bad-size-full}, i.e., $|\mH_{r}| \leq \wt{O}(n)$ holds with high probability for any $r \in [R]$.

Combining Eq.~\eqref{eq:regret-last1} and Eq.~\eqref{eq:regret-last3}, we conclude 
\begin{align*}
\sum_{t \in [T]}\ell_{t}(i_t) -\sum_{t \in [T]}\ell_{t}(i^{*})  \leq \wt{O}\left(\sqrt{nT}\right) 
\end{align*}
holds with probability at least $1-1/(nT)^{\omega(1)}$.
We complete the proof here.
\end{proof}
